// frontend file and run the script again.
/**
 * Writing and editing a discussion post in the demo data: the shape of the
 * input, how it is validated, and how it becomes a `posts.json` record.
 *
 * Three places run this code: the "Start a discussion" composer (to show field
 * errors as the user types), the mock API in the browser, and the Vite
 * dev-server plugin that writes accepted posts into `src/mocks/data/posts.json`.
 * So it stays pure and uses relative imports - the plugin loads it outside the
 * app's aliases.
 */
import type { PostRecord } from '../types/demoSearch.js';
import { bannedWordMessage, containsBannedWord } from './moderation.js';
import { normalizeTagList, validateTag } from './tags.js';

export interface DemoPostInput {
  title: string;
  content: string;
  tags: string[];
}

export const DEMO_POST_LIMITS = {
  titleMax: 140,
  /** "No length limit" for the writer; this only stops runaway pastes. */
  contentMax: 50_000,
  tagsMin: 1,
  tagsMax: 10,
} as const;

export type DemoPostField = keyof DemoPostInput;
/** Keyed by `DemoPostField`. */
export type DemoPostFieldErrors = Record<string, string[]>;

export type DemoPostValidation =
  { ok: true; post: DemoPostInput } | { ok: false; fieldErrors: DemoPostFieldErrors };

/**
 * Checks a post and returns it trimmed with normalised tags. Accepts
 * `unknown` because the mock API and the plugin pass parsed request bodies.
 */
export function validateDemoPost(input: unknown): DemoPostValidation {
  const raw = (input ?? {}) as Partial<Record<DemoPostField, unknown>>;
  const title = typeof raw.title === 'string' ? raw.title.trim() : '';
  const content = typeof raw.content === 'string' ? raw.content.trim() : '';
  const rawTags = Array.isArray(raw.tags)
    ? raw.tags.filter((tag): tag is string => typeof tag === 'string')
    : [];
  const tags = normalizeTagList(rawTags);
  const errors: DemoPostFieldErrors = {};

  if (!title) errors['title'] = ['Add a title so people know what this is about.'];
  else if (title.length > DEMO_POST_LIMITS.titleMax)
    errors['title'] = [`Keep the title under ${DEMO_POST_LIMITS.titleMax} characters.`];
  else if (containsBannedWord(title)) errors['title'] = [bannedWordMessage('title')];

  if (!content) errors['content'] = ['Write something before posting.'];
  else if (content.length > DEMO_POST_LIMITS.contentMax)
    errors['content'] = [`Posts can be up to ${DEMO_POST_LIMITS.contentMax} characters.`];
  else if (containsBannedWord(content)) errors['content'] = [bannedWordMessage('post')];

  if (tags.length < DEMO_POST_LIMITS.tagsMin) errors['tags'] = ['Pick at least 1 tag.'];
  else if (tags.length > DEMO_POST_LIMITS.tagsMax)
    errors['tags'] = [`Use at most ${DEMO_POST_LIMITS.tagsMax} tags.`];
  else {
    for (const tag of tags) {
      const result = validateTag(tag);
      if (!result.valid) {
        errors['tags'] = [result.message];
        break;
      }
    }
  }

  return Object.keys(errors).length > 0
    ? { ok: false, fieldErrors: errors }
    : { ok: true, post: { title, content, tags } };
}

/** The next `post_NNNN` id after the highest one in `posts`. */
export function nextDemoPostId(posts: readonly PostRecord[]): string {
  const highest = posts.reduce((max, post) => {
    const match = /^post_(\d+)$/.exec(post.id);
    return match ? Math.max(max, Number(match[1])) : max;
  }, 0);
  return `post_${String(highest + 1).padStart(4, '0')}`;
}

/** A brand-new published record, as it is stored in posts.json. */
export function createPostRecord(
  input: DemoPostInput,
  id: string,
  authorRefId: string,
  now: string,
): PostRecord {
  return {
    id,
    authorRefId,
    title: input.title,
    content: input.content,
    tags: input.tags,
    relatedCompanyIds: [],
    createdAt: now,
    updatedAt: null,
    commentCount: 0,
    status: 'published',
  };
}

/** `record` with the edited text and tags, marked as edited. */
export function applyPostEdit(record: PostRecord, input: DemoPostInput, now: string): PostRecord {
  return {
    ...record,
    title: input.title,
    content: input.content,
    tags: input.tags,
    updatedAt: now,
  };
}
